import logging
import json
try:
    from json.decoder import JSONDecodeError
except ImportError:
    JSONDecodeError = ValueError
from six.moves.urllib.request import urlopen, Request
from six.moves.urllib.error import HTTPError, URLError
from taf.hw.rf_switch.devices.rf_switch import RfSwitch
from taf.hw.rf_switch.exceptions import (RfSwitchConnectionFailed,
                                         RfSwitchActionFailed,
                                         RfSwitchActionNotSupported)


ni_logger = logging.getLogger(__name__)


class NationalInstruments(RfSwitch):
    """
    Module to control National Instruments RF switches.
    """

    def __init__(self, ip, port=8081):
        super().__init__()
        self.ip = ip
        self.port = port

    def _check_state(self, state, port_in, port_out):
        for slot in state:
            if slot.get("name", None) == port_in:
                for channel in slot.get("channels", []):
                    if channel.get("name", None) == port_out and channel.get("state", False):
                        return
        raise RfSwitchActionFailed("Requested action not consistent with received state.")

    def _send_http_request(self, command):
        url = f"http://{self.ip}:{self.port}/plugins/niss/connect"
        try:
            req = Request(url, data=bytes(command.encode('utf-8')), headers={"Content-Type": "application/json"})
            handle = urlopen(req)
            try:
                return handle.read()
            except OSError:
                raise RfSwitchConnectionFailed("No connection to RF switch.")
            finally:
                handle.close()
        except (URLError, HTTPError):
            raise RfSwitchConnectionFailed("No connection to RF switch.")

    def connect_ports(self, port_in, port_out):
        port_in = port_in.lower()
        command = json.dumps({"slot": port_in, "channel": port_out})
        response_text = self._send_http_request(command)
        try:
            response = json.loads(response_text)
            if not response.get("success", False):
                raise RfSwitchActionFailed("Requested action failed: {}".format(response.get("message", "")))
            self._check_state(response.get("status", []), port_in, port_out)
        except JSONDecodeError:
            raise RfSwitchConnectionFailed(f"Could not parse response from server:\n{response_text}")

    def disconnect_ports(self, port_in, port_out='1'):
        msg = "Action not supported for this device."
        raise RfSwitchActionNotSupported(msg)

    def get_port_in_status(self, port_in):
        msg = "Action not implemented for this device, please contact library maintainers if it is needed."
        raise RfSwitchActionNotSupported(msg)

    def get_port_out_status(self, port_out):
        msg = "Action not implemented for this device, please contact library maintainers if it is needed."
        raise RfSwitchActionNotSupported(msg)

    def get_connected_ports(self):
        msg = "Action not implemented for this device, please contact library maintainers if it is needed."
        raise RfSwitchActionNotSupported(msg)


class PXI2546(NationalInstruments):
    def __init__(self, ip, port):
        super().__init__(ip, port)


